package com.franco.desco.adapter.in.web.catalog;
import com.franco.desco.adapter.in.web.common.*;import com.franco.desco.adapter.in.web.openapi.OpenApiConstants;import com.franco.desco.application.catalog.CatalogCommands.*;import com.franco.desco.application.catalog.port.in.CatalogUseCase;import io.swagger.v3.oas.annotations.Operation;import io.swagger.v3.oas.annotations.Parameter;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.constraints.Pattern;import org.springframework.http.ResponseEntity;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/v1/geografia") @Tag(name="Geografía",description="Cascada territorial de apoyo para formularios.") @SecurityRequirement(name=OpenApiConstants.BEARER_AUTH) @Validated public class GeographyController{private final CatalogUseCase u;private final ApiResponseFactory res;public GeographyController(CatalogUseCase u,ApiResponseFactory res){this.u=u;this.res=res;}
 @GetMapping("/departamentos") @Operation(operationId="geografiaListarDepartamentos",summary="Listar departamentos") public ResponseEntity<ApiResponse<List<CatalogResponses.Department>>>departments(@Parameter(hidden=true) HttpServletRequest r){return res.from(u.departments(new ListDepartments()),r,x->x.stream().map(d->new CatalogResponses.Department(d.departamentoCodigo(),d.departamentoNombre())).toList());}
 @GetMapping("/departamentos/{codigo}/provincias") @Operation(operationId="geografiaListarProvincias",summary="Listar provincias") public ResponseEntity<ApiResponse<List<CatalogResponses.Province>>>provinces(@PathVariable @Pattern(regexp="\\d{2}") String codigo,@Parameter(hidden=true) HttpServletRequest r){return res.from(u.provinces(new ListProvinces(codigo)),r,x->x.stream().map(d->new CatalogResponses.Province(d.provinciaCodigo(),d.provinciaNombre())).toList());}
 @GetMapping("/provincias/{codigo}/distritos") @Operation(operationId="geografiaListarDistritos",summary="Listar distritos") public ResponseEntity<ApiResponse<List<CatalogResponses.District>>>districts(@PathVariable @Pattern(regexp="\\d{4}") String codigo,@Parameter(hidden=true) HttpServletRequest r){return res.from(u.districts(new ListDistricts(codigo)),r,x->x.stream().map(d->new CatalogResponses.District(d.distritoCodigo(),d.distritoNombre())).toList());}
 @GetMapping("/distritos/{codigo}/centros-poblados") @Operation(operationId="geografiaListarCentrosPoblados",summary="Listar centros poblados") public ResponseEntity<ApiResponse<List<CatalogResponses.PopulationCenter>>>centers(@PathVariable @Pattern(regexp="\\d{6}") String codigo,@Parameter(hidden=true) HttpServletRequest r){return res.from(u.populationCenters(new ListPopulationCenters(codigo)),r,x->x.stream().map(d->new CatalogResponses.PopulationCenter(d.centroPobladoId(),d.codigoInei(),d.centroPobladoNombre())).toList());}
}
